class Solution {
public:
    int countDistinctStrings(string s, int k) {
        const int MOD = 1000000007;
        int exponent = (int)s.size() - k + 1;
        long long answer = 1, base = 2;
        while (exponent > 0) {
            if (exponent & 1) answer = answer * base % MOD;
            base = base * base % MOD;
            exponent >>= 1;
        }
        return (int)answer;
    }
};
